'use strict';
const $=id=>document.getElementById(id);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const state={day:3,view:'story',filter:'All stops',overview:false,photo:0,base:'streets'};
const photoKeys=Object.keys(PHOTOS), reduced=window.matchMedia('(prefers-reduced-motion: reduce)').matches;
const videoKeys=Object.keys(VIDEOS);
let map,markers,routeLayer,markerIndex={},tileLayer,tileRun=0,tileTimer,toastTimer;
const currentDay=()=>TRIP.days.find(d=>d.date===state.day);
const weekday=n=>new Date(Date.UTC(2026,9,n,12)).toLocaleDateString('en-US',{weekday:'short',timeZone:'UTC'});
const mapsURL=p=>'https://www.google.com/maps/search/?api=1&query='+encodeURIComponent(p.query);
const ext=(url,label)=>`<a href="${esc(url)}" target="_blank" rel="noopener noreferrer">${esc(label)} <span aria-hidden="true">↗</span></a>`;
function links(p,pin=true){return `<div class="stop-links">${ext(p.url,p.source==='Learn more'?'Learn more':p.source)}${ext(mapsURL(p),'Google Maps')}${pin&&p.xy?`<button data-pin="${p.id}">Locate ⌖</button>`:''}</div>`;}
function toast(t){clearTimeout(toastTimer);$('toast').textContent=t;$('toast').hidden=false;toastTimer=setTimeout(()=>$('toast').hidden=true,4500);}
function setHash(){let h=state.view==='explore'?(state.overview?'route':'day-'+state.day):state.view;try{history.replaceState(null,'','#'+h);}catch(e){/* Local previews may restrict history. */}}
function setView(v,hash=true){if(!['story','explore','photos'].includes(v))return;state.view=v;const heroVideo=$('coverVideo');if(heroVideo){if(v==='story'&&!reduced)heroVideo.play().catch(()=>{});else heroVideo.pause();}['story','explore','photos'].forEach(id=>$(id).hidden=id!==v);document.querySelectorAll('.main-nav [data-view]').forEach(b=>b.setAttribute('aria-current',b.dataset.view===v?'page':'false'));if(v==='explore'){ensureMap();requestAnimationFrame(()=>{map?.invalidateSize({pan:false});state.overview?drawRoute():drawDayMap();});}if(hash)setHash();}
function setMobile(v){$('explore').dataset.mobile=v;$('detailsView').setAttribute('aria-pressed',v==='details');$('mapView').setAttribute('aria-pressed',v==='map');if(v==='map')requestAnimationFrame(()=>{map?.invalidateSize({pan:false});fitVisible();});}
function selectDay(n,open=true,preserveView=false){n=Number(n);if(!TRIP.days.some(d=>d.date===n))return;state.day=n;state.overview=false;state.filter='All stops';$('kindFilter').value='All stops';renderDay();if(open)setView('explore');else if(map)drawDayMap();$('journalScroll').scrollTop=0;if(open&&!preserveView)setMobile('details');updateTour();setHash();}
function renderDay(){const d=currentDay(),ch=TRIP.chapters[d.phase];$('dayEyebrow').textContent=`${weekday(d.date)}, ${d.date} October · Chapter ${d.phase+1} / ${ch.name}`;$('dayTitle').textContent=d.title;$('daySubtitle').textContent=d.subtitle;$('previousDay').disabled=d.date===3;$('nextDay').disabled=d.date===18;document.querySelectorAll('[data-date]').forEach(b=>b.setAttribute('aria-current',Number(b.dataset.date)===d.date?'date':'false'));const pill=document.querySelector(`[data-date="${d.date}"]`);if(pill){const t=$('timeline');if(pill.offsetLeft<t.scrollLeft||pill.offsetLeft+pill.offsetWidth>t.scrollLeft+t.clientWidth)t.scrollLeft= Math.max(0,pill.offsetLeft-t.clientWidth/2+pill.offsetWidth/2);}
 const items=d.items.map((e,i)=>({...e,n:i+1})).filter(e=>state.filter==='All stops'||TRIP.places[e.id].kind===state.filter);
 let html=d.photo&&state.filter==='All stops'?`<button class="day-photo" data-photo="${d.photo}" aria-label="Open photo: ${esc(PHOTOS[d.photo].title)}"><img src="${PHOTOS[d.photo].src}" alt="${esc(PHOTOS[d.photo].alt)}"><span>Our photo · open ↗</span></button>`:'';
 html+=`<div class="section-label">${state.filter==='All stops'?'The day, in places':esc(state.filter)} · ${items.length}</div><div class="stops">`;
 html+=items.map(e=>{const p=TRIP.places[e.id];return `<article class="stop" id="stop-${p.id}"><div class="stop-num">${String(e.n).padStart(2,'0')}</div><div class="kind">${esc(p.kind)}</div><h3>${esc(p.name)}</h3>${e.time?`<p class="record">${esc(e.time)}</p>`:''}<p>${esc(p.desc)}</p>${e.note?`<p class="extra">${esc(e.note)}</p>`:''}${links(p)}</article>`;}).join('');
 if(!items.length)html+='<p class="empty">No stops in this category for this day. Choose “All stops” or explore another date.</p>';
 html+='</div>';
 if(d.stay&&state.filter==='All stops'){const p=TRIP.places[d.stay];html+=`<section class="stay"><span class="kind">${d.stay==='conde'?'A pause to rest · day use':'Our base'}</span><h3>${esc(p.name)}</h3><p>${esc(p.desc)}</p>${links(p)}</section>`;}
 if(d.reflection&&state.filter==='All stops')html+=`<aside class="reflection"><span class="eyebrow" style="display:block;font:700 9px Arial;letter-spacing:.13em;margin-bottom:7px">A moment to reflect</span>${esc(d.reflection)}</aside>`;
 if(d.logistics&&state.filter==='All stops')html+=`<details class="logistics"><summary>Travel notes & recorded timing</summary><p>${esc(d.logistics)}</p></details>`;
 if(state.filter==='All stops'){
  const clips=videoKeys.map(key=>({key,...VIDEOS[key]})).filter(v=>v.day===d.date);
  if(clips.length)html+=`<section class="day-videos"><div class="section-label">Moments in motion · ${clips.length}</div><div class="day-video-grid">${clips.map(v=>videoCard(v)).join('')}</div></section>`;
 }
 const next=TRIP.days.find(x=>x.date===d.date+1);html+=next?`<button class="next-day" data-day="${next.date}"><span><small>Continue · October ${next.date}</small>${esc(next.title)}</span><span aria-hidden="true">→</span></button>`:'<button class="next-day" data-view="story"><span><small>The journey, complete</small>Back to the beginning</span><span aria-hidden="true">↗</span></button>';
 $('dayContent').innerHTML=html;$('dayContent').classList.remove('coming-in');requestAnimationFrame(()=>$('dayContent').classList.add('coming-in'));$('dayAnnouncement').textContent=`October ${d.date}. ${d.title}.`;updateMapCaption();}
function ensureMap(){if(map)return; if(!window.L){$('mapNote').textContent='The interactive map could not initialize. Every stop still has a Google Maps link.';return;}
 map=L.map('map',{zoomControl:false,scrollWheelZoom:true,minZoom:4,maxZoom:19,attributionControl:true}).setView([-14.4,-73.7],6);L.control.zoom({position:'bottomright'}).addTo(map);map.attributionControl.setPrefix('<a href="https://leafletjs.com/" target="_blank" rel="noopener">Leaflet</a>');map.attributionControl.addAttribution('Atlas: <a href="https://www.naturalearthdata.com/" target="_blank" rel="noopener">Natural Earth</a>');
 map.createPane('atlas');map.getPane('atlas').style.zIndex=150;
 L.geoJSON(GEOGRAPHY,{pane:'atlas',style:f=>({color:'#93ac9b',weight:1,fillColor:f.properties.name==='Peru'?'#ecebdd':'#dce2d3',fillOpacity:1,interactive:false})}).addTo(map);
 markers=L.layerGroup().addTo(map);routeLayer=L.layerGroup().addTo(map);
 if(window.ResizeObserver)new ResizeObserver(()=>{map.invalidateSize({pan:false});}).observe($('map'));
 setBase('streets');}
function updateMapCaption(){const d=currentDay();$('mapDate').textContent=state.overview?'03—18 October 2026':`${weekday(d.date)}, ${d.date} October · Day ${d.date-2} of 16`;$('mapTitle').textContent=state.overview?'The journey, in sequence':d.title;updateTour();$('fitDay').textContent=state.overview?'⌖ Back to selected day':'⌖ Fit this day';updateMapNote();}
function updateMapNote(extra=''){const base=state.overview?'Route order: Lima → Cusco → Machu Picchu → Cusco → Puno → Arequipa → Huacachina → Paracas → Lima. Lines are schematic.':'Numbered pins match the day’s list; they do not imply a timed order. Approximate site references.';$('mapNote').textContent=extra||(state.base==='atlas'?'Atlas mode · Works offline. '+base:base);}
function setBase(base){state.base=base;$('atlasMode').setAttribute('aria-pressed',base==='atlas');$('streetMode').setAttribute('aria-pressed',base==='streets');clearTimeout(tileTimer);++tileRun;if(tileLayer){tileLayer.remove();tileLayer=null;}updateMapNote();if(base==='streets'&&map)loadTiles('maptiler',tileRun);}
function loadTiles(provider,run){if(run!==tileRun||state.base!=='streets')return;let errors=0,loaded=false;const key=SITE_CONFIG.maptilerKey||'';const url=provider==='maptiler'?'https://api.maptiler.com/maps/streets-v4/{z}/{x}/{y}.png?key='+encodeURIComponent(key):'https://tile.openstreetmap.org/{z}/{x}/{y}.png';const layer=L.tileLayer(url,{tileSize:256,maxZoom:19,attribution:(provider==='maptiler'?'&copy; <a href="https://www.maptiler.com/copyright/" target="_blank" rel="noopener">MapTiler</a> ':'')+'&copy; <a href="https://www.openstreetmap.org/copyright" target="_blank" rel="noopener">OpenStreetMap</a>'});tileLayer=layer;
 const fallback=()=>{if(run!==tileRun||tileLayer!==layer)return;clearTimeout(tileTimer);layer.remove();tileLayer=null;if(provider==='maptiler'){updateMapNote('Loading the alternate street map…');loadTiles('osm',run);}else{setBase('atlas');updateMapNote('Street tiles are unavailable. The embedded atlas, pins, photos and itinerary remain available.');}};
 layer.on('tileload',()=>{if(tileLayer!==layer)return;loaded=true;clearTimeout(tileTimer);updateMapNote();});layer.on('tileerror',()=>{if(++errors>=4)fallback();});layer.addTo(map);tileTimer=setTimeout(()=>{if(!loaded)fallback();},9000);}
function pinIcon(n,hotel=false,selected=false){return L.divIcon({className:'',html:`<div class="pin ${hotel?'hotel-pin':''} ${selected?'selected':''}">${hotel?'⌂':n}</div>`,iconSize:[30,30],iconAnchor:[15,15],popupAnchor:[0,-16]});}
function popupFor(p,e){return `<div class="kind">${esc(p.kind)}${e?.time?' · '+esc(e.time):''}</div><h3>${esc(p.name)}</h3><p>${esc(p.desc)}</p>${links(p,false)}`;}
function dayPlaces(){const d=currentDay();const pts=d.items.map((e,i)=>({p:TRIP.places[e.id],e,n:i+1})).filter(x=>x.p.xy&&(state.filter==='All stops'||x.p.kind===state.filter));if(d.stay&&state.filter==='All stops')pts.push({p:TRIP.places[d.stay],e:{},n:'H'});return pts;}
function drawDayMap(){if(!map)return;state.overview=false;markers.clearLayers();routeLayer.clearLayers();markerIndex={};for(const {p,e,n} of dayPlaces()){const m=L.marker(p.xy,{icon:pinIcon(n,n==='H'),title:p.name,alt:p.name,keyboard:true}).addTo(markers).bindPopup(popupFor(p,e),{maxWidth:280,autoPanPaddingTopLeft:[20,100],autoPanPaddingBottomRight:[20,90]}).bindTooltip(`<b>${esc(p.name)}</b><br>${esc(e.time||p.kind)}`,{direction:'top',offset:[0,-18]});m.on('click',()=>highlight(p.id));markerIndex[p.id]=m;}updateMapCaption();fitVisible();}
function fitVisible(){if(!map)return;const pts=state.overview?TRIP.route.map(r=>r.xy):dayPlaces().map(x=>x.p.xy);map.invalidateSize({pan:false});if(pts.length){map.fitBounds(L.latLngBounds(pts),{paddingTopLeft:[45,110],paddingBottomRight:[45,115],maxZoom:state.overview?7:15,animate:!reduced});}else{const region=[[-13.52,-71.98],[-15.75,-69.8],[-16.4,-71.54],[-14.08,-75.76],[-12.10,-77.03]][currentDay().phase];map.setView(region,10,{animate:false});}}
function highlight(id){document.querySelectorAll('.stop.active').forEach(x=>x.classList.remove('active'));const card=$('stop-'+id);if(card){card.classList.add('active');if(window.innerWidth>760)card.scrollIntoView({block:'nearest',behavior:reduced?'auto':'smooth'});}}
function focusPin(id){const p=TRIP.places[id];if(!p?.xy)return;state.overview=false;setView('explore');setMobile('map');requestAnimationFrame(()=>{if(!markerIndex[id])drawDayMap();const m=markerIndex[id];if(m){map.setView(p.xy,Math.max(14,map.getZoom()),{animate:!reduced});m.openPopup();highlight(id);}});}
function showRoute(){$('tourBar').hidden=false;state.overview=true;setView('explore');setMobile('map');requestAnimationFrame(drawRoute);updateTour();setHash();}
function drawRoute(){if(!map)return;state.overview=true;markers.clearLayers();routeLayer.clearLayers();markerIndex={};const route=TRIP.route;const order=[0,1,2,1,3,4,5,6,0].map(i=>route[i].xy);L.polyline(order,{color:'#b78242',weight:3,opacity:.8,dashArray:'6 8',interactive:false}).addTo(routeLayer);for(const r of route){const icon=L.divIcon({className:'',html:`<div class="route-pin">${esc(r.label)}</div>`,iconSize:[r.label.includes('·')?55:35,35],iconAnchor:[18,18]});L.marker(r.xy,{icon,title:r.name,alt:r.name}).addTo(markers).bindTooltip(r.name,{permanent:true,direction:'right',offset:[23,0],className:'place-label'}).bindPopup(`<div class="kind">Trip progression · ${esc(r.label)}</div><h3>${esc(r.name)}</h3><p>${esc(r.note)}</p><div class="stop-links"><button data-day="${r.day}">Explore this chapter →</button>${r.name==='Lima'?'<button data-day="3">Arrival day →</button>':''}</div>`,{maxWidth:280});}updateMapCaption();fitVisible();}
function openPhoto(key){let i=photoKeys.indexOf(key);if(i<0)return;state.photo=i;renderPhoto();if(!$('lightbox').open)$('lightbox').showModal();}
function renderPhoto(){const p=PHOTOS[photoKeys[state.photo]];$('fullPhoto').src=p.src;$('fullPhoto').alt=p.alt;$('photoTitle').textContent=p.title;$('photoCaption').textContent=p.caption;$('photoCount').textContent=`Our photographs · ${state.photo+1} / ${photoKeys.length}`;$('photoDayLink').href='#day-'+p.day;$('photoDayLink').dataset.day=p.day;$('previousPhoto').disabled=state.photo===0;$('nextPhoto').disabled=state.photo===photoKeys.length-1;}
function videoCard(v){return `<button class="video-card" data-video="${esc(v.key)}" aria-label="Play video: ${esc(v.title)}"><img src="${v.poster}" loading="lazy" alt="${esc(v.alt)}"><span class="video-play" aria-hidden="true">▶</span><span class="video-card-label"><small>October ${v.day} · Our video</small>${esc(v.title)}</span></button>`;}
function openVideo(key){const v=VIDEOS[key];if(!v)return;const dialog=$('videoDialog'),player=$('tripVideo');$('videoDate').textContent=`October ${v.day}, 2026 · Our video`;$('videoTitle').textContent=v.title;$('videoCaption').textContent=v.caption;$('videoDayButton').dataset.day=v.day;player.poster=v.poster;player.src=v.src;dialog.showModal();player.load();}
function closeVideo(){const player=$('tripVideo');player.pause();player.removeAttribute('src');player.load();$('videoDialog').close();}
function exportKml(){const x=v=>esc(v);const pts=Object.values(TRIP.places).filter(p=>p.xy);const kml='<?xml version="1.0" encoding="UTF-8"?><kml xmlns="http://www.opengis.net/kml/2.2"><Document><name>Peru 2026 · Completed trip</name><description>Approximate site references from the completed journey. Not navigation routes.</description>'+pts.map(p=>`<Placemark><name>${x(p.name)}</name><description>${x(p.desc+' Learn more: '+p.url)}</description><Point><coordinates>${p.xy[1]},${p.xy[0]},0</coordinates></Point></Placemark>`).join('')+'</Document></kml>';const u=URL.createObjectURL(new Blob([kml],{type:'application/vnd.google-earth.kml+xml'}));const a=document.createElement('a');a.href=u;a.download='Peru_2026_Visited_Places.kml';a.click();setTimeout(()=>URL.revokeObjectURL(u),1500);}
function handleHash(){const h=location.hash.slice(1);if(/^day-(\d+)$/.test(h)){const n=Number(h.slice(4));if(n>=3&&n<=18)selectDay(n);else setView('story',false);}else if(h==='route')showRoute();else if(h==='photos'||h==='story')setView(h,false);}
document.addEventListener('click',event=>{const b=event.target.closest('[data-view],[data-day],[data-date],[data-pin],[data-photo],[data-video]');if(!b)return;if(b.dataset.view){setView(b.dataset.view);return;}if(b.dataset.day||b.dataset.date){event.preventDefault();if($('lightbox').open)$('lightbox').close();if($('videoDialog').open)closeVideo();if($('itineraryDialog').open)$('itineraryDialog').close();selectDay(b.dataset.day||b.dataset.date);return;}if(b.dataset.pin){focusPin(b.dataset.pin);return;}if(b.dataset.photo)openPhoto(b.dataset.photo);if(b.dataset.video)openVideo(b.dataset.video);});
$('previousDay').addEventListener('click',()=>selectDay(state.day-1));$('nextDay').addEventListener('click',()=>selectDay(state.day+1));$('begin').addEventListener('click',()=>selectDay(3));$('routeStart').addEventListener('click',showRoute);$('wholeRoute').addEventListener('click',showRoute);$('fitDay').addEventListener('click',()=>{if(state.overview){state.overview=false;drawDayMap();setHash();}else fitVisible();});$('kindFilter').addEventListener('change',event=>{state.filter=event.target.value;state.overview=false;renderDay();drawDayMap();setHash();});$('atlasMode').addEventListener('click',()=>setBase('atlas'));$('streetMode').addEventListener('click',()=>setBase('streets'));$('detailsView').addEventListener('click',()=>setMobile('details'));$('mapView').addEventListener('click',()=>setMobile('map'));
$('about').addEventListener('click',()=>{$('aboutDialog').showModal();});['closeAbout','closeAboutBottom'].forEach(id=>$(id).addEventListener('click',()=>$('aboutDialog').close()));$('exportKml').addEventListener('click',exportKml);$('closePhoto').addEventListener('click',()=>$('lightbox').close());$('previousPhoto').addEventListener('click',()=>{if(state.photo>0){state.photo--;renderPhoto();}});$('nextPhoto').addEventListener('click',()=>{if(state.photo<photoKeys.length-1){state.photo++;renderPhoto();}});
$('closeVideo').addEventListener('click',closeVideo);$('videoDialog').addEventListener('close',()=>{const player=$('tripVideo');player.pause();player.removeAttribute('src');player.load();});$('videoDialog').addEventListener('click',e=>{if(e.target===$('videoDialog'))closeVideo();});
$('fullscreen').addEventListener('click',async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else if(document.documentElement.requestFullscreen)await document.documentElement.requestFullscreen();else toast('Use your browser’s full-screen option.');}catch(e){toast('Full screen is unavailable in this preview. Open the downloaded file in your browser.');}});
document.addEventListener('keydown',e=>{if(['INPUT','SELECT','TEXTAREA'].includes(e.target.tagName))return;if($('lightbox').open){if(e.key==='ArrowLeft'&&state.photo>0){state.photo--;renderPhoto();e.preventDefault();}if(e.key==='ArrowRight'&&state.photo<photoKeys.length-1){state.photo++;renderPhoto();e.preventDefault();}}});

function setMapInfo(open){$('mapContext').hidden=!open;$('mapNote').hidden=!open;$('mapInfoToggle').setAttribute('aria-expanded',String(open));$('mapInfoToggle').textContent=open?'ⓘ Hide info':'ⓘ Map info';}
function updateTour(){
 $('tourStatus').textContent=state.overview?'16 days · Full route':`Day ${state.day-2} / 16 · Oct ${state.day} · ${currentDay().title}`;
 $('tourPrevious').disabled=!state.overview&&state.day===3;
 $('tourNext').disabled=!state.overview&&state.day===18;
}
function stepTour(delta){const n=state.overview?(delta>0?3:18):Math.min(18,Math.max(3,state.day+delta));selectDay(n,true,true);}
function showItinerary(){$('itineraryDialog').showModal();}
$('mapInfoToggle').addEventListener('click',()=>setMapInfo($('mapInfoToggle').getAttribute('aria-expanded')!=='true'));
$('closeMapInfo').addEventListener('click',()=>{setMapInfo(false);$('mapInfoToggle').focus();});
$('tourPrevious').addEventListener('click',()=>stepTour(-1));
$('tourNext').addEventListener('click',()=>stepTour(1));
$('tourClose').addEventListener('click',()=>{$('tourBar').hidden=true;});
$('allDays').addEventListener('click',showItinerary);
$('routeOverview').addEventListener('click',showRoute);
$('browseFromStart').addEventListener('click',()=>{$('itineraryDialog').close();selectDay(3);});
$('closeItinerary').addEventListener('click',()=>$('itineraryDialog').close());
$('itineraryList').innerHTML=TRIP.days.map(d=>`<article class="itinerary-day"><button data-day="${d.date}"><span class="itinerary-date">${weekday(d.date)}<b>${d.date}</b>Oct</span><span><small>Chapter ${d.phase+1} · ${esc(TRIP.chapters[d.phase].name)}</small><strong>${esc(d.title)}</strong><span class="itinerary-summary">${esc(d.subtitle)}</span></span><span aria-hidden="true">↗</span></button><ul>${d.items.map(e=>`<li>${esc(TRIP.places[e.id].name)}${e.time?' <small>· '+esc(e.time)+'</small>':''}</li>`).join('')}</ul>${d.stay?`<p class="itinerary-stay">Our base · ${esc(TRIP.places[d.stay].name)}</p>`:''}</article>`).join('');

window.addEventListener('hashchange',handleHash);
$('coverPhoto').style.backgroundImage=`url("${PHOTOS.machu.src}")`;
$('chapters').innerHTML=TRIP.chapters.map((c,i)=>`<button class="chapter-link" data-day="${c.day}" title="${esc(c.summary)}"><span class="chapter-index">0${i+1} / ${c.dates}</span><strong>${esc(c.name)}</strong><small>${esc(c.region)} ↗</small></button>`).join('');
$('timeline').innerHTML=TRIP.days.map(d=>`<button class="day-pill" data-date="${d.date}" style="--pillcolor:${TRIP.chapters[d.phase].color}" aria-label="${weekday(d.date)}, October ${d.date}: ${esc(d.title)}"><small>${weekday(d.date)}</small><b>${String(d.date).padStart(2,'0')}</b></button>`).join('');
$('photoGrid').innerHTML=photoKeys.map(k=>{const p=PHOTOS[k];return `<button class="photo-card" data-photo="${k}" aria-label="Open photo: ${esc(p.title)}"><img src="${p.src}" loading="lazy" alt="${esc(p.alt)}"><span><small>October ${p.day} · Our photo</small>${esc(p.title)} ↗</span></button>`;}).join('');
$('videoGrid').innerHTML=videoKeys.map(k=>videoCard({key:k,...VIDEOS[k]})).join('');
renderDay();handleHash();
